async function handleCheckoutReturn(){
 const params=new URLSearchParams(location.search);const state=params.get('checkout');
 if(!state)return;
 if(isPhonePortrait())goSetupPage(5,true);
 if(state==='cancelled'){
   showCheckoutNotice('Payment cancelled. No story credits were charged.');
   history.replaceState({},document.title,location.pathname);
   return;
 }
 if(state!=='success')return;
 const sessionId=params.get('session_id')||'';
 if(!currentUser){showCheckoutNotice('Payment received. Sign in to the account that made the purchase to confirm your credits.');return}
 if(!sessionId){showCheckoutNotice('Payment completed, but Moonbeam could not read the checkout reference. Your payment is still protected.', 'error');return}
 showCheckoutNotice('Payment received — confirming your new story credits…');
 try{
   const token=await currentAccessToken();
   const r=await fetch(`/api/checkout-status?session_id=${encodeURIComponent(sessionId)}`,{headers:{'Authorization':`Bearer ${token}`}});
   const data=await r.json().catch(()=>({}));
   if(!r.ok)throw new Error(data.error||'Could not confirm payment.');
   if(data.paid){
     if(Number.isFinite(Number(data.balance)))renderStoryCredits(Number(data.balance));else await loadStoryCredits();
     await refreshStoryCreditConsentUI().catch(()=>{});
     showCheckoutNotice(`${Number(data.credits)||'Your'} new story credits have been added. Enjoy your next adventure!`,'success');
     history.replaceState({},document.title,location.pathname);
   }else{
     showCheckoutNotice('Stripe is still confirming the payment. Your credits will appear as soon as it completes.');
     setTimeout(()=>handleCheckoutReturn(),1800);
   }
 }catch(e){
   console.error('checkout return',e);showCheckoutNotice('Your payment may have succeeded, but Moonbeam could not confirm it yet. Refresh this page in a moment; credits are granted server-side and cannot be lost.','error');
 }
}


function clearStoryConsentAttention(){
 const box=$('storySupplyConsent'),check=$('storySupplyConsentCheck');
 if(!box)return;
 box.classList.remove('consent-attention');
 const msg=box.querySelector('.story-consent-hint');
 if(msg)msg.remove();
 if(check)check.removeAttribute('aria-invalid');
}
function showStoryConsentAttention(){
 const box=$('storySupplyConsent'),check=$('storySupplyConsentCheck');
 if(!box||!check)return;
 clearStoryConsentAttention();
 const msg=document.createElement('div');
 msg.className='story-consent-hint';
 msg.setAttribute('role','alert');
 msg.textContent=t().tick;
 box.appendChild(msg);
 check.setAttribute('aria-invalid','true');
 // Re-adding the class after a frame guarantees the flash animation restarts on repeated clicks.
 requestAnimationFrame(()=>box.classList.add('consent-attention'));
 box.scrollIntoView?.({block:'center',behavior:'smooth'});
 try{check.focus({preventScroll:true})}catch{check.focus?.()}
}
async function refreshStoryCreditConsentUI(accessToken=''){
 const box=$('storySupplyConsent'),check=$('storySupplyConsentCheck');
 if(!box||!check)return {consentRequired:false};
 try{
   const token=accessToken||await currentAccessToken();
   if(!token||!currentUser){clearStoryConsentAttention();box.classList.add('hidden');box.dataset.batchId='';check.checked=false;return {consentRequired:false}}
   const r=await fetch('/api/story-consent',{headers:{'Authorization':`Bearer ${token}`}});
   const data=await r.json().catch(()=>({}));
   if(!r.ok)throw new Error(data.error||'Could not check story credits.');
   if(!data.has_credit||!data.consent_required){clearStoryConsentAttention();box.classList.add('hidden');box.dataset.batchId='';check.checked=false;return {consentRequired:false}}
   const batchId=String(data.batch_id||'');
   if(box.dataset.batchId!==batchId){check.checked=false;box.dataset.batchId=batchId;clearStoryConsentAttention()}
   // V62: show the acknowledgement quietly in its normal grey state before the customer presses Create.
   box.classList.remove('hidden');
   return {consentRequired:true,batchId};
 }catch(e){
   console.warn('story consent preview',e);
   return {consentRequired:false,error:e};
 }
}
async function prepareStoryCreditConsent(accessToken){
 const box=$('storySupplyConsent'),check=$('storySupplyConsentCheck');
 if(!box||!check)return true;
 try{
   const state=await refreshStoryCreditConsentUI(accessToken);
   if(state.error)throw state.error;
   if(!state.consentRequired)return true;
   const batchId=String(state.batchId||box.dataset.batchId||'');
   if(!check.checked){showStoryConsentAttention();return false}
   clearStoryConsentAttention();
   const accept=await fetch('/api/story-consent',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${accessToken}`},body:JSON.stringify({batchId})});
   const accepted=await accept.json().catch(()=>({}));
   if(!accept.ok||accepted.accepted!==true)throw new Error(accepted.error||'Could not record your confirmation.');
   box.classList.add('hidden');box.dataset.batchId='';check.checked=false;
   return true;
 }catch(e){
   $('status').innerHTML='<span class="error">'+escapeHtml(e.message||String(e))+'</span>';
   return false;
 }
}
