const activeNarrationAudios=new Set();
function splitNarrationSentences(text){const m=String(text||'').match(/[^.!?…]+(?:[.!?…]+[”’\"']?|$)/g);return (m&&m.length?m:[String(text||'')]).map(x=>x.trim()).filter(Boolean)}
