 const a=accountUI213(),input=$('accountNewEmail'),status=$('accountEmailStatus'),save=$('accountSaveEmail');
 const nextEmail=(input?.value||'').trim().toLowerCase();
 if(!nextEmail||!input?.checkValidity()){if(status)status.innerHTML=`<span class="error">${escapeHtml(a.enterEmail)}</span>`;return}
 if(nextEmail===(currentUser.email||'').trim().toLowerCase()){if(status)status.innerHTML=`<span class="error">${escapeHtml(a.sameEmail)}</span>`;return}
 if(status)status.textContent=a.changingEmail;if(save)save.disabled=true;
